# -*- coding: utf-8 -*-
from __future__ import print_function

import base64
import errno
import os
import struct
import tempfile

ASSET_DIRECTORY = os.path.join(tempfile.gettempdir(), "online-picons-assets")

ASSET_DATA = {
    "dot-checking.png": "",
    "dot-green.png": "",
    "dot-yellow.png": "",
    "dot-red.png": "",
    "check.png": "",
    "rss.png": "",
}


def asset_path(name):
    return os.path.join(ASSET_DIRECTORY, name)


def ensure_assets():
    try:
        os.makedirs(ASSET_DIRECTORY)
    except OSError as error:
        if error.errno != errno.EEXIST:
            raise

    for name, encoded in ASSET_DATA.items():
        data = base64.b64decode(encoded)
        path = asset_path(name)
        try:
            if os.path.isfile(path) and os.path.getsize(path) == len(data):
                continue
        except OSError:
            pass
        temporary = "%s.tmp-%d" % (path, os.getpid())
        output = open(temporary, "wb")
        try:
            output.write(data)
        finally:
            output.close()
        try:
            os.rename(temporary, path)
        except OSError:
            try:
                os.unlink(path)
            except OSError:
                pass
            os.rename(temporary, path)
    return ASSET_DIRECTORY


def validate_assets():
    expected = set([
        "dot-checking.png",
        "dot-green.png",
        "dot-yellow.png",
        "dot-red.png",
        "check.png",
        "rss.png",
    ])
    if set(ASSET_DATA) != expected:
        raise RuntimeError("The runtime asset list is incomplete")
    for name, encoded in ASSET_DATA.items():
        data = base64.b64decode(encoded)
        if not data.startswith(b"\x89PNG\r\n\x1a\n"):
            raise RuntimeError("%s is not a PNG file" % name)
        width, height = struct.unpack(">II", data[16:24])
        expected_size = (300, 300) if name == "rss.png" else (32, 32)
        if (width, height) != expected_size:
            raise RuntimeError("%s has an unexpected image size" % name)
    return True


if __name__ == "__main__":
    validate_assets()
    print("Validated %d runtime PNG assets" % len(ASSET_DATA))

